#pragma once#include <macros/IntrusivePtr.h>#include <vector>#include <string>enum eRawGeometryTypes{  ertUnknown      = 0,  ertFlatNoBorder = 0x001,  ertFlatH5       = 0x002,  ertRound        = 0x004,  ertBitBlt       = 0x008,  ertPolygone     = 0x010,  ertLine         = 0x020,  ertLineX2       = 0x040,  ertLineX3       = 0x080,  ertLineX5       = 0x100,  ertBlackR       = 0x200,  ertTriOutData   = 0x400,};enum eSubObjectTypes{  esotUnknown        = 0,  esotDigital        = 0x001,  esotAnalog         = 0x002,  esotVariable       = 0x004,  esotNumConst       = 0x008,  esotSignal         = 0x010,  esotPageConnector  = 0x020,  esotSignalConnector= 0x040,  esotSignalAnalog   = esotSignal|esotAnalog,  esotSignalDigital  = esotSignal|esotDigital,  esotVariableAnalog = esotVariable|esotAnalog,  esotVariableDigital= esotVariable|esotDigital,  esotPageConnectorAnalog   = esotPageConnector|esotAnalog,  eesotPageConnectorDigital  = esotPageConnector|esotDigital,  esotSignalConnectorAnalog   = esotSignalConnector|esotAnalog,  esotSignalConnectorDigital  = esotSignalConnector|esotDigital,};struct IGraphObjPoints;typedef TIntrusivePtr<IGraphObjPoints> tGraphObjPointsPtr_;struct STextOnObj{  std::string text;  POINT pt[2];};struct IGraphObjPoints : public ref_counted{  virtual ~IGraphObjPoints(){}  bool operator==( tGraphObjPointsPtr_ &thr )  {    return m_ID==thr->GetID();  }  virtual int GetID() const = 0;  virtual void Complete() = 0;  virtual void AddPoints( PPOINT pt, int count, eRawGeometryTypes eType, LOGPEN pen ) = 0;  virtual void SetPolyline( PPOINTS pt, int count, LOGPEN pen ) = 0;  virtual void SetPolygone( PPOINTS pt, int count, LOGPEN pen, LOGBRUSH32 brush ) = 0;  virtual void SetRect( RECT &rc, eRawGeometryTypes eType, LOGPEN pen, LOGBRUSH32 brush ) = 0;  virtual BOOL IsRect() const = 0;  virtual eRawGeometryTypes GetRawDrawType() const = 0;  virtual eSubObjectTypes GetSubObjectType() const = 0;  virtual void CombineSubObjectType( eSubObjectTypes t ) = 0;  virtual BOOL IsDiagonalLine() const = 0;  virtual CRect GetBoundRect() const = 0;  virtual bool GetConnectRect( CRect &miniRect ) = 0;  virtual void AddText( LPCSTR pszText, const POINT &pt1, const POINT &pt2 ) = 0;  virtual BOOL IsContainText() const = 0;  virtual std::string GetName() const = 0;  virtual std::string GetTagName() = 0;  virtual DWORD IsLineCon( CRect rc, PPOINT pt = NULL ) const = 0;  virtual CPoint GetFrontPt() const = 0;  virtual CPoint GetBackPt() const = 0;  virtual STextOnObj* GetNearestText( POINT &pt ) = 0;  int nInConnection;protected:  int m_ID;};